<?php require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';?><main class="container-fluid py-4 px-lg-4"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="mb-0"><?=esAdministrador()?'Ventas registradas':'Mis ventas'?></h2><span class="text-secondary">Cada venta descuenta automáticamente el stock.</span></div><a class="btn btn-primary" href="index.php?c=venta&a=crear">+ Nueva venta</a></div><div class="card"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Fecha</th><?php if(esAdministrador()):?><th>Vendedor</th><?php endif;?><th>Campaña / Producto</th><th>Cliente</th><th>Total</th><th>Entrega</th></tr></thead><tbody><?php if(!$ventas):?><tr><td colspan="6" class="vacio">No hay ventas registradas.</td></tr><?php else:foreach($ventas as $v):?><tr><td><?=e($v['fecha_venta'])?></td><?php if(esAdministrador()):?><td><?=e($v['vendedor'])?></td><?php endif;?><td><?=e($v['campania'])?><small class="d-block text-secondary"><?=e($v['producto'])?> × <?=e($v['cantidad'])?></small></td><td><?=e($v['cliente'])?><small class="d-block text-secondary"><?=e($v['telefono_cliente'])?></small></td><td><strong>$<?=number_format($v['total'],2,',','.')?></strong></td><td><?php if($v['estado_entrega']==='ENTREGADA'):?><span class="badge text-bg-success">Entregada</span><small class="d-block"><?=e($v['fecha_entrega'])?></small><?php elseif(esAdministrador()):?><form method="post" action="index.php?c=venta&a=entregar"><input type="hidden" name="id" value="<?=$v['id']?>"><button class="btn btn-sm btn-outline-success">Marcar entregada</button></form><?php else:?><span class="badge text-bg-warning">Pendiente</span><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></div></main><?php require __DIR__.'/../footer.php';?>
